from common import *

L = "LEG"
NOCONTRACT = "No customer agreement template, security addendum or DPA was located. Business plan section 14 states contracting principles in draft."

au(L, 1, title="Contract framework, order of precedence and negotiation authority",
   status="proposed-target-state", rationale=NOCONTRACT,
   target="Echelon offers a counsel-drafted master services agreement with order forms, a security addendum, a data processing addendum and a service level schedule. The signed agreement takes precedence over any online terms, which cannot change the customer's obligations without written amendment. We will review customer paper; deviations from our standard positions are approved by the managing member after counsel review and recorded in a contract exceptions register (BP 14.08), and every accepted obligation is extracted into an obligations register with an owner.",
   current="Not established.",
   intended="Engage counsel to draft a standard agreement set before the first paid engagement.",
   provable="Nothing.",
   statement="Echelon's standard customer agreement set is being prepared and is not yet available. We are willing to review customer paper with counsel.",
   kind="planned", controls=["LEG-001", "LEG-003"], evrs=["LEG-001", "LEG-002"],
   freshness="per-event", mechanism="event-driven-automated", automation="partial", impl="medium", recur="low",
   qd=dict(sub="Contract framework", concern="The contractual structure is clear, stable and enforceable.",
           risk="Conflicting or unilaterally changeable terms leave obligations uncertain.",
           src=[D("SRC-INTERAGENCY-TPRM-2023"), S("SRC-SA-SIG", rel="informed-by"), S("SRC-ECH-BUSINESS-PLAN", rel="informed-by")],
           ind=ALLI, prod=ALLP),
   questions=[
    Q("Do you have a standard master services agreement, and will you contract on our paper?",
      ["Provide your standard contract.", "Will you sign our MSA?"]),
    Q("What is the order of precedence among the MSA, order forms, security addendum, DPA and any online terms, and can online terms change without our written agreement?",
      ["Can you modify terms by updating a web page?"], imp="high"),
    Q("Which terms are non-negotiable for you, and which customer terms have you declined in the past?",
      ["What are your standard redlines?"], imp="medium", rc="customer-preference"),
    Q("Who in your company can approve contract deviations, and is legal counsel involved?",
      ["Do you have in-house or outside counsel?"], imp="medium", rc="customer-preference"),
   ])

au(L, 2, title="Information security addendum and flow-down of safeguards",
   status="proposed-target-state", rationale=NOCONTRACT + " The Secure Construction Standard and Unbound requirements describe the intended technical commitments.",
   target="We sign a security addendum committing to specific, verifiable safeguards rather than only 'reasonable security': encryption in transit and at rest with managed keys (SEC-CRYPTO-001), phishing-resistant MFA for administrative access, deny-by-default authorization with tenant isolation (SEC-AUTH-001), logging and retention periods, vulnerability remediation timelines and secure development rules. We contractually maintain safeguards consistent with the GLBA Safeguards requirements applicable to our customers, flow equivalent obligations down to subcontractors with access to customer data, and accept termination for uncured material security breach.",
   current="Not established.",
   intended="Draft security addendum aligned to the Secure Construction Standard once adopted.",
   provable="Draft standard only.",
   statement="A security addendum with specific safeguards is planned. We expect to accept GLBA-consistent safeguard obligations and subcontractor flow-down.",
   kind="planned", controls=["LEG-001", "LEG-003"], evrs=["LEG-001", "LEG-002"],
   policies=["SEC-CRYPTO-001", "SEC-AUTH-001", "SEC-SUPPLY-001"], freshness="per-event", mechanism="event-driven-automated",
   automation="partial", impl="medium", recur="low",
   qd=dict(sub="Security addendum", concern="Security obligations are contractually binding and specific.",
           risk="Vague security terms leave the customer without remedy after a breach.",
           src=[D("SRC-INTERAGENCY-TPRM-2023"), S("SRC-NIST-CSF-2.0", "GV.SC-05"), S("SRC-SA-SIG", rel="informed-by")],
           ind=FIN + DAF, prod=ALLP),
   questions=[
    Q("Will you sign our information security addendum, and which requirements would you need to modify?",
      ["Review and accept our security exhibit."], imp="critical"),
    Q("Will you contractually commit to implement and maintain safeguards for customer information consistent with the GLBA Safeguards Rule or the interagency safeguards guidelines?",
      ["Will you agree to GLBA service provider safeguard terms?"],
      src=[D("SRC-FTC-SAFEGUARDS-RULE", "16 CFR 314.4(f)"), D("SRC-INTERAGENCY-GLBA-SAFEGUARDS"), D("SRC-GLBA")],
      rc="legal-regulatory", auth="FTC; federal banking agencies", imp="critical",
      scope="The rule obliges the financial institution to require safeguards of its service providers by contract; it reaches Echelon through that contract."),
    Q("Will you flow down equivalent security obligations to every subcontractor that accesses our data?",
      ["Do your subcontractor agreements include security requirements?"], src=[S("SRC-NYDFS-PART-500", "500.11"), S("SRC-ISO-27001-2022", "A.5.20")]),
    Q("Will you commit in the contract to specific technical measures, such as encryption, MFA and log retention, or only to reasonable security?",
      ["List the security controls you will commit to contractually."], imp="medium", rc="customer-preference"),
    Q("Does the agreement allow us to terminate for a material security failure or repeated failure to remediate findings?",
      ["Is a security breach a termination event?"], imp="medium"),
   ])

au(L, 3, title="Incident and breach notification obligations",
   status="proposed-target-state", rationale=NOCONTRACT + " Unbound requires incident detection, communication and lessons learned (SOC2-026) and a notification event catalog (UNB-RCN-PLT-002); none operates.",
   target="We commit to notify affected customers without undue delay and in any case within 24 hours of determining that a security incident has affected or is reasonably likely to affect their data or services, and within the shorter of any period required by law applicable to the customer: for bank customers, as soon as possible when an incident has materially disrupted or degraded services for four hours or more (bank service provider notification rule); for SEC-regulated customers, within 72 hours of becoming aware of a breach of customer information (Regulation S-P). Notices state what is known, affected data, actions taken and a contact, and are updated as facts develop. Incident clocks are computed per customer from a register of each customer's notification obligations. We bear the reasonable cost of notification, forensic investigation and credit monitoring caused by our breach.",
   current="Not established.",
   intended="Build notification obligation register and incident runbook before production.",
   provable="Nothing.",
   statement="Incident notification commitments, including regulatory timelines that apply to bank and SEC-regulated customers, are planned but not yet contractually offered or operated.",
   kind="planned", controls=["LEG-002"], evrs=["LEG-003", "LEG-002"],
   requirements=["SOC2-026", "UNB-RCN-PLT-002"], freshness="per-event", mechanism="event-driven-automated", automation="high",
   impl="medium", recur="low",
   oq=["Is Echelon a 'bank service provider' under the 2021 notification rule for any intended customer, given Unbound serves DAF sponsors rather than banks?"],
   qd=dict(sub="Breach notification", concern="The customer learns of incidents quickly enough to meet its own obligations.",
           risk="Late or incomplete notice causes the customer to breach its regulatory or contractual duties.",
           src=[S("SRC-STATE-BREACH-LAWS", rel="informed-by"), S("SRC-NIST-SP800-61-R3", rel="informed-by"), S("SRC-SA-SIG", rel="informed-by")],
           ind=ALLI, prod=ALLP, imp="critical"),
   questions=[
    Q("What is your contractual timeframe for notifying us of a security incident or data breach, and what will the notice contain?",
      ["How quickly will you tell us about a breach?"]),
    Q("As a bank service provider, will you notify us as soon as possible when an incident has materially disrupted or degraded your services to us for four or more hours?",
      ["Do you comply with the computer-security incident notification rule for bank service providers?"],
      src=[D("SRC-CIRN-RULE-2021")], ind=["banking"], rc="legal-regulatory", auth="OCC, FDIC, Federal Reserve",
      scope="Applies only where Echelon provides covered services to a banking organization."),
    Q("Will you notify us within 72 hours of becoming aware of a breach in security resulting in unauthorized access to customer information, as Regulation S-P requires of our service providers?",
      ["Do you meet SEC Regulation S-P service provider notification requirements?"],
      src=[D("SRC-SEC-REG-SP-2024", "17 CFR 248.30")], ind=["wealth-management", "financial-services"], rc="legal-regulatory", auth="SEC",
      scope="Applies where the customer is a covered institution under Regulation S-P; the rule requires the customer to obtain this commitment."),
    Q("Who bears the costs of breach notification, forensic investigation, credit monitoring and regulatory response caused by an incident at your company?",
      ["Will you reimburse breach response costs?"], imp="high"),
    Q("Will you notify us of security incidents that do not involve our data but could affect the security or availability of the service?",
      ["Do you report incidents affecting other customers or your infrastructure?"], imp="medium", rc="customer-preference"),
   ])

au(L, 4, title="Limitation of liability, indemnities and ability to pay",
   status="proposed-target-state", rationale=NOCONTRACT + " Business plan section 14.06 states a draft position on liability and risk allocation. No insurance is in place to fund liability.",
   target="Our standard cap is the greater of fees paid in the prior 12 months or a fixed amount, with a higher super-cap for breach of confidentiality, data protection and security obligations, set no higher than the insurance limits we actually carry so the commitment is fundable. Fraud, willful misconduct and our IP infringement indemnity are uncapped or separately capped. We indemnify customers against third-party IP infringement claims, including claims arising from code produced with AI tools, and against third-party claims and regulatory penalties arising from our breach where legally insurable and permissible. Loss of or corruption of customer data caused by our breach is treated as direct damages. We disclose our insurance limits so customers can judge whether the cap is backed.",
   current="Not established.",
   intended="Set caps after insurance is placed; align with LEG-004 control.",
   provable="Nothing.",
   statement="Standard liability and indemnity terms are not yet set. We will align our liability caps with insurance we actually hold so commitments are backed.",
   kind="planned", controls=["LEG-004", "INS-001"], evrs=["INS-004", "LEG-001"],
   freshness="P1Y", mechanism="periodic-manual", automation="low", impl="low", recur="low",
   residual=["A small company may be unable to pay a large judgment above insurance regardless of contract terms."],
   challenge=CH(
     customer_intent="Be made whole if the vendor causes a loss.",
     adverse_outcome="Customer bears breach costs because the vendor's cap is low or the vendor cannot pay.",
     conventional_control_effectiveness="High or uncapped liability negotiated from a startup is often illusory: without assets or insurance it cannot be collected.",
     legally_required="No statute sets vendor liability caps; regulations require customers to manage third-party risk, which includes contract remedies.",
     contractually_required="Banks and enterprises commonly require super-caps for data breach.",
     historical_convention="Cap at 12 months' fees with negotiated data breach super-cap of multiples of fees.",
     architectural_elimination="Designs that never hold funds (CNV-LEG-001) and minimize sensitive data held reduce the maximum plausible loss.",
     automatic_enforcement="Not applicable.",
     continuous_evidence="Certificates of insurance matched to contractual caps.",
     stronger_alternative="Caps tied to verifiable insurance plus loss-reducing architecture.",
     alternative_verifiable="Yes, via certificates and policy endorsements.",
     customer_acceptance_likelihood="Uncertain; procurement teams may insist on fixed multiples.",
     invalidating_conditions="Insurance lapses or excludes the relevant loss; cap set above coverage.",
     conventional_cost="Accepting uninsured super-caps creates existential exposure for Echelon.",
     alternative_cost="Insurance premium: medium for a startup, order-of-magnitude judgment, not sourced.",
     alternative_risks="Insurance limits shared across customers (aggregate erosion).",
     supporting_arguments=["Honest about collectability; aligns incentives."],
     opposing_arguments=["Customers may see insurance-linked caps as the vendor limiting its exposure."],
     technical_effectiveness="equivalent", institutional_acceptance="uncertain"),
   qd=dict(sub="Liability and indemnity", concern="Losses caused by the vendor are allocated fairly and are collectible.",
           risk="The customer bears losses caused by the vendor because of low caps, exclusions or vendor inability to pay.",
           src=[D("SRC-INTERAGENCY-TPRM-2023"), S("SRC-ECH-BUSINESS-PLAN", rel="informed-by"), S("SRC-SA-SIG", rel="informed-by")],
           ind=ALLI, prod=ALLP, imp="high"),
   questions=[
    Q("What is your standard limitation of liability, and which claims are excluded from the cap?",
      ["Provide your liability cap terms."]),
    Q("Will you accept uncapped or super-capped liability for data breach, breach of confidentiality and gross negligence?",
      ["What is your data breach super-cap?"], imp="critical"),
    Q("Will you indemnify us against third-party intellectual property infringement claims arising from the service, including code or content produced with AI tools?",
      ["Do you provide an IP indemnity?"], src=[S("SRC-ECH-BUSINESS-PLAN", rel="informed-by"), S("SRC-NIST-AI-600-1", rel="informed-by")]),
    Q("Will you indemnify us for regulatory fines, penalties and third-party claims resulting from your breach, to the extent legally permissible?",
      ["Do you cover regulatory penalties caused by you?"]),
    Q("How does your liability cap relate to your insurance limits and your ability to pay a judgment?",
      ["Is your liability backed by insurance or assets?"], rc="customer-preference", ind=FIN + DAF),
    Q("Will you treat loss or corruption of our data caused by your breach as direct damages rather than excluded consequential damages?",
      ["Is data loss excluded as consequential?"], imp="medium"),
   ])

au(L, 5, title="Data protection terms: DPA, service provider terms, location, deletion and legal hold",
   status="proposed-target-state", rationale=NOCONTRACT + " Unbound requires legal holds that reach processors (UNB-XIN-REC-001), privacy-aware retention and deletion (SOC2-032) and a published subprocessor register (UNB-XIN-SAS-011).",
   target="We sign a DPA that meets GDPR Article 28 where EU personal data is processed and that includes CCPA service provider terms (use only for the specified business purposes, no sale or sharing, no combining with other data) for US customers. Data is hosted and supported in the United States unless the customer agrees otherwise, and any transfer uses a recognized mechanism. At termination we return data in an open format and delete it, including from backups on their normal expiry, within a stated period, and certify deletion in writing. Legal hold notices from customers suspend deletion for the identified scope and are acknowledged.",
   current="Not established.",
   intended="DPA template drafted with counsel; deletion and legal hold supported by Unbound data lifecycle design.",
   provable="Requirements only.",
   statement="A data processing addendum, deletion certification and legal hold support are planned. Data residency commitments will be offered once hosting is selected.",
   kind="planned", controls=["LEG-001", "LEG-005"], evrs=["LEG-001", "LEG-004", "LEG-006"],
   requirements=["UNB-XIN-REC-001", "SOC2-032", "UNB-XIN-SAS-011"], freshness="per-event", mechanism="event-driven-automated",
   automation="high", impl="medium", recur="low",
   qd=dict(sub="Data protection terms", concern="Personal data processing terms satisfy the customer's legal obligations.",
           risk="Customer is non-compliant with privacy law because the vendor contract lacks required terms.",
           src=[S("SRC-US-STATE-PRIVACY-LAWS", rel="informed-by"), S("SRC-SA-SIG", rel="informed-by")],
           ind=ALLI, prod=ALLP, imp="high"),
   questions=[
    Q("Will you sign a data processing agreement that meets GDPR Article 28 processor requirements where EU personal data is involved?",
      ["Provide your DPA."], src=[D("SRC-GDPR", "Art. 28"), S("SRC-EDPB-GL-07-2020", rel="informed-by")], jur=["EU"], rc="legal-regulatory",
      auth="EU data protection authorities", scope="Applies only if EU personal data is processed; Unbound targets US sponsors."),
    Q("Will you contractually agree to act as a service provider under the CCPA, restricting use of personal information to the business purposes we specify?",
      ["Will you sign CCPA service provider terms?"], src=[D("SRC-CCPA-CPRA")], jur=["US-state:CA"], rc="legal-regulatory", auth="California Privacy Protection Agency",
      scope="Applies where the customer is a covered business; many nonprofits are outside CCPA."),
    Q("Will any of our data be stored, processed or accessed from outside the United States, and what transfer mechanisms apply?",
      ["Where is our data located?"], src=[S("SRC-EU-SCC-2021", rel="informed-by"), S("SRC-EU-US-DPF", rel="informed-by")], jur=GLB),
    Q("At contract end, will you return our data and then delete it, including backups, within a defined period and certify deletion in writing?",
      ["Do you provide a certificate of destruction?"], src=[S("SRC-ISO-27001-2022", "A.8.10"), S("SRC-NIST-SP800-88", rel="informed-by")]),
    Q("Will you preserve our data under a legal hold when we notify you of litigation or an investigation, even if retention periods would otherwise delete it?",
      ["Do you support legal holds?"], src=[D("SRC-ECH-UNB-BASELINE")], imp="medium"),
   ])

au(L, 6, title="Termination, transition assistance, assignment and subcontracting",
   status="proposed-target-state", rationale=NOCONTRACT + " Unbound defines sponsor exit (REQ-X-061) and vendor exit responsibility (UNB-GAP-028); EU DORA requires exit strategies and termination rights for ICT services supporting critical functions.",
   target="Customers may terminate for convenience on notice, for cause, on our change of control, on our insolvency and when directed by their regulator, without penalty in the last three cases. On any termination we provide transition assistance for up to 12 months at contracted rates, including full data export, continued operation during migration and cooperation with the successor. We may not assign the agreement without consent except to a successor that assumes all obligations, with notice and a customer termination right. New subcontractors with access to customer data are notified 30 days in advance through the subprocessor register, and customers may object and terminate if the objection cannot be resolved.",
   current="Not established.",
   intended="Include in standard agreement.",
   provable="Nothing.",
   statement="Termination, transition assistance, assignment and subprocessor change terms are planned for the standard agreement.",
   kind="planned", controls=["LEG-001", "LEG-005", "FST-005"], evrs=["LEG-001", "LEG-004", "FST-005"],
   requirements=["REQ-X-061", "UNB-GAP-028", "UNB-XIN-SAS-011"], freshness="per-event", mechanism="event-driven-automated",
   automation="partial", impl="low", recur="low",
   qd=dict(sub="Termination and exit", concern="The customer can leave the relationship safely and controls who handles its data.",
           risk="Customer is locked in, loses data at exit, or finds its data with an unknown subcontractor or acquirer.",
           src=[D("SRC-INTERAGENCY-TPRM-2023"), D("SRC-EU-DORA", "Art. 28"), S("SRC-EBA-OUTSOURCING-GL", rel="informed-by")],
           ind=FIN + DAF, prod=ALLP, imp="high"),
   questions=[
    Q("What termination rights do we have, including for convenience, cause, change of control and regulatory direction?",
      ["Under what conditions can we terminate?"]),
    Q("What transition assistance will you provide on termination, for how long and at what cost?",
      ["Will you help us migrate to another provider?"], imp="critical"),
    Q("Can you assign the agreement to a successor or acquirer without our consent?",
      ["Is the contract assignable?"], imp="medium"),
    Q("Will you notify us before engaging a new subcontractor that will access our data, and may we object?",
      ["How are subprocessor changes communicated?"], src=[D("SRC-GDPR", "Art. 28"), D("SRC-ECH-UNB-BASELINE"), D("SRC-INTERAGENCY-TPRM-2023")]),
    Q("Will you accept termination if our regulator directs us to end or change the relationship?",
      ["Do you accept regulator-directed termination?"], src=[D("SRC-EU-DORA", "Art. 28"), S("SRC-EBA-OUTSOURCING-GL", rel="informed-by")], ind=FIN,
      rc="supervisory-guidance", scope="Legally required in contracts of EU financial entities under DORA; a supervisory expectation elsewhere."),
   ])

