# ---------------------------------------------------------------- INS
I = "INS"
NOINS = "No insurance policy, certificate, quotation or broker engagement was located. Business plan section 14.07 states a draft position on insurance and risk transfer only."

au(I, 1, title="Cyber liability insurance (first and third party)",
   status="unknown", rationale=NOINS,
   target="Echelon carries cyber liability insurance from an admitted carrier rated A- or better by AM Best, covering first-party costs (forensics, notification, credit monitoring, data restoration, business interruption including dependent business interruption from cloud and AI providers, extortion) and third-party liability (privacy and network security claims, regulatory defense and fines where insurable, media liability). Limits are set from a broker-supported analysis of the largest contractual commitments and plausible loss scenarios rather than chosen in advance, and are increased before onboarding customers whose contracts require more. Exclusions and minimum-security warranties are reviewed against our actual controls.",
   current="Unknown; no evidence of any policy.",
   intended="Engage a broker and bind cyber coverage before the first production customer.",
   provable="Nothing.",
   statement="Echelon does not currently hold a cyber insurance policy that we can evidence. We plan to bind cyber coverage before handling customer production data.",
   kind="not-available", controls=["INS-001", "INS-002"], evrs=["INS-001", "INS-002"],
   freshness="P1Y", mechanism="external-attestation", automation="low", impl="medium", recur="medium",
   oq=["What cyber limits are realistically available to a pre-revenue Indiana LLC without a SOC report, and at what premium?"],
   qd=dict(sub="Cyber insurance", concern="Funds exist to respond to a breach and pay resulting claims.",
           risk="A breach at the vendor leaves response costs and liabilities unfunded.",
           src=[D("SRC-INTERAGENCY-TPRM-2023"), S("SRC-AICPA-TSC", "CC9.1"), S("SRC-SA-SIG", rel="informed-by")],
           ind=ALLI, prod=ORG, imp="critical"),
   questions=[
    Q("Do you carry cyber liability insurance? Provide carrier, policy period, aggregate and per-claim limits, and retention.",
      ["Provide a certificate of cyber insurance.", "What are your cyber coverage limits?"]),
    Q("Does the policy cover both first-party costs (forensics, notification, business interruption, extortion) and third-party liability (privacy claims, regulatory defense)?",
      ["What does your cyber policy cover?"], imp="high"),
    Q("Does the policy cover incidents originating at your cloud provider, subcontractors or AI model providers, including dependent business interruption?",
      ["Is contingent business interruption covered?"], imp="medium", rc="customer-preference"),
    Q("Are there exclusions or conditions, such as war, infrastructure failure, unencrypted devices or failure to maintain minimum security, that could void coverage for a likely incident?",
      ["List material exclusions in your cyber policy."], imp="medium", rc="customer-preference"),
    Q("Does the cyber policy cover regulatory fines and penalties where insurable by law?",
      ["Are regulatory penalties insured?"], imp="medium", rc="customer-preference"),
   ])

au(I, 2, title="Technology errors and omissions (professional liability)",
   status="unknown", rationale=NOINS,
   target="Echelon carries technology errors and omissions insurance, typically combined with cyber in one tower, covering financial loss to customers from errors in the service, including miscalculation of fees, balances, NAV or grant amounts and errors in AI-assisted outputs. Because coverage is claims-made, we maintain continuous coverage and purchase an extended reporting period of at least three years if the policy is cancelled or the company winds down.",
   current="Unknown.",
   intended="Bind with cyber coverage.",
   provable="Nothing.",
   statement="Technology errors and omissions coverage is not currently in place. We plan to bind it together with cyber coverage.",
   kind="not-available", controls=["INS-001"], evrs=["INS-001", "INS-002"],
   freshness="P1Y", mechanism="external-attestation", automation="low", impl="medium", recur="medium",
   qd=dict(sub="Technology E&O", concern="Financial loss from vendor errors is insured.",
           risk="A processing error causes customer financial loss the vendor cannot pay.",
           src=[D("SRC-INTERAGENCY-TPRM-2023"), S("SRC-SA-SIG", rel="informed-by")], ind=ALLI, prod=ORG, imp="high"),
   questions=[
    Q("Do you carry technology errors and omissions insurance, and what are the limits?",
      ["Do you have professional liability coverage?"]),
    Q("Is the E&O policy written on a claims-made basis, and will you maintain an extended reporting period after termination or cessation of business?",
      ["Will you buy tail coverage?"], imp="medium"),
    Q("Does E&O cover errors in financial calculations, such as fees, balances, NAV and grant amounts, and errors in AI-generated outputs?",
      ["Are AI errors excluded from your E&O?"], ind=DAF + FIN, prod=UNB, src=[S("SRC-NIST-AI-600-1", rel="informed-by"), D("SRC-INTERAGENCY-TPRM-2023")],
      rc="customer-preference"),
   ])

au(I, 3, title="Crime, fidelity and social engineering coverage matched to the service's loss scenarios",
   status="unknown", rationale=NOINS + " Unbound's design states it never holds or moves funds and cannot execute payments (CNV-LEG-001), which changes which crime losses it can cause.",
   target="Echelon carries commercial crime coverage including employee dishonesty, third-party (client property) coverage, computer fraud, funds transfer fraud and social engineering, with limits based on the loss scenarios the service can actually cause. Because Unbound prepares but does not execute payments and never holds funds, the dominant insurable scenario is a fraudulent payment instruction prepared through the platform and released by the sponsor; we document this scenario and coordinate coverage with the sponsor's own crime policy so there is no gap between them.",
   current="Unknown.",
   intended="Bind crime coverage with third-party extension; document loss scenarios with the broker.",
   provable="Nothing.",
   statement="Crime and fidelity coverage is not currently in place. The platform is designed not to hold or move customer funds.",
   kind="not-available", controls=["INS-001"], evrs=["INS-001", "INS-004"],
   requirements=["CNV-LEG-001", "CNV-PAY-001"], freshness="P1Y", mechanism="external-attestation", automation="low",
   impl="medium", recur="low",
   challenge=CH(
     customer_intent="Recovery if vendor personnel or attackers cause theft of the customer's funds.",
     adverse_outcome="Fraudulent grant payments or diverted funds.",
     conventional_control_effectiveness="Crime insurance compensates after the fact; it does not prevent loss and often has low social engineering sublimits.",
     legally_required="No for Echelon.",
     contractually_required="Common in financial services vendor contracts, especially for vendors with access to payment systems.",
     historical_convention="Fidelity bond with third-party coverage.",
     architectural_elimination="Unbound never holds funds and cannot execute payments (CNV-LEG-001); payee bank changes and releases require sponsor authority with separation of duties.",
     automatic_enforcement="Authority matrix refuses unmapped commands (CNV-GOV-010); payee change notifications (CNV-PLT-011).",
     continuous_evidence="Authority and release logs.",
     stronger_alternative="Architectural prevention plus coordinated, not duplicated, coverage.",
     alternative_verifiable="Partially; design is verifiable once built and tested.",
     customer_acceptance_likelihood="Uncertain; procurement checklists often require crime coverage regardless of architecture.",
     invalidating_conditions="Any path by which Echelon personnel or agents can alter payee data or release payments.",
     conventional_cost="Low to medium premium.",
     alternative_cost="Engineering cost already within product scope.",
     alternative_risks="Residual social engineering of sponsor staff is not prevented by architecture.",
     supporting_arguments=["Reduces the probability of the insured event, not only its cost."],
     opposing_arguments=["Insurance is still the expected backstop and costs little relative to the risk."],
     technical_effectiveness="stronger", institutional_acceptance="uncertain"),
   qd=dict(sub="Crime and fidelity", concern="Theft or fraud involving vendor personnel or systems is recoverable.",
           risk="Customer funds are stolen through vendor personnel or vendor-prepared instructions without recovery.",
           src=[D("SRC-INTERAGENCY-TPRM-2023"), S("SRC-SA-SIG", rel="informed-by"), D("SRC-ECH-UNB-BASELINE")], ind=DAF + FIN, prod=UNB, imp="high"),
   questions=[
    Q("Do you carry commercial crime or fidelity coverage for employee dishonesty, including third-party coverage for theft of client property?",
      ["Do you have a fidelity bond?"]),
    Q("Does your crime coverage include social engineering and funds transfer fraud, and what are the sublimits?",
      ["What is your social engineering sublimit?"], imp="medium"),
    Q("Given that your service prepares but does not execute payments, how is your insurance aligned with the losses your service could realistically cause, and with our own crime policy?",
      ["Which loss scenarios does your insurance address?"], rc="customer-preference", reqs=["CNV-LEG-001"]),
   ])

